// Hole Edge Check: a DFM checker feature for Onshape, generated by Claude from rules/hole-edge.json.
// Rule: on a flat sheet-metal or plate part, every round hole's rim must sit at least factor x thickness from the
// part's outer edge (default 2.0 x, the upper end of Fabcon's 1.5-2x guideline; see docs/sources.md).
// Pick the plate's flat face; the feature finds the round holes in it, measures rim-to-edge, colours the holes that
// fail red and reports the count. It adds no geometry.
//
// Same check as checker/hole_edge.py, which is the tested reference.
// STATUS: not yet compiled in Onshape (see README "What runs").
//
// HOW TO PASTE: in a new Feature Studio keep the two lines Onshape generates ("FeatureScript NNNN;" and the
// import of onshape/std/common.fs) and paste everything BELOW the marker under them.
// ---------------- paste from here ----------------

const THICKNESS_BOUNDS = { (millimeter) : [0.1, 2.0, 50.0] } as LengthBoundSpec;
const FACTOR_BOUNDS = { (unitless) : [0.5, 2.0, 10.0] } as RealBoundSpec;
const TOL = 1e-6 * meter;

annotation { "Feature Type Name" : "Hole Edge Check",
             "Feature Type Description" : "DFM: each hole's rim must be at least factor x thickness from the part edge" }
export const holeEdgeCheck = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Plate face", "Filter" : EntityType.FACE && GeometryType.PLANE, "MaxNumberOfPicks" : 1 }
        definition.face is Query;

        annotation { "Name" : "Material thickness" }
        isLength(definition.thickness, THICKNESS_BOUNDS);

        annotation { "Name" : "Factor (x thickness)" }
        isReal(definition.factor, FACTOR_BOUNDS);
    }
    {
        const edges = qAdjacent(definition.face, AdjacencyType.EDGE, EntityType.EDGE);

        // depth of the part along the face normal, to tell through-holes from counterbores and blind pockets
        const cs = coordSystem(evPlane(context, { "face" : definition.face }));
        const partBox = evBox3d(context, { "topology" : qOwnerBody(definition.face), "cSys" : cs });
        const partDepth = partBox.maxCorner[2] - partBox.minCorner[2];

        // round holes = closed circular edges (length 2 pi r) that are inner loops of the face and whose wall runs
        // the full part depth. Skipped: arcs such as corner fillets, the outer rim of a round plate, blind pockets
        // and counterbores (wall shorter than the part, whatever the floor looks like).
        var holes = [];
        for (var e in evaluateQuery(context, qGeometry(edges, GeometryType.CIRCLE)))
        {
            const circle = evCurveDefinition(context, { "edge" : e });
            const r = circle.radius;
            if (abs(evLength(context, { "entities" : e }) - 2 * PI * r) > TOL)
                continue;

            // inner loop: a point just outside the circle still lies on the face; for the outer rim it does not
            const p = evEdgeTangentLine(context, { "edge" : e, "parameter" : 0 }).origin;
            const eps = 0.01 * r;
            const probe = p + normalize(p - circle.coordSystem.origin) * eps;
            if (evDistance(context, { "side0" : probe, "side1" : definition.face }).distance > 0.5 * eps)
                continue;

            const wall = qSubtraction(qAdjacent(e, AdjacencyType.EDGE, EntityType.FACE), definition.face);
            const wallBox = evBox3d(context, { "topology" : wall, "cSys" : cs });
            const wallDepth = wallBox.maxCorner[2] - wallBox.minCorner[2];
            if (wallDepth >= partDepth - TOL)
                holes = append(holes, e);
        }
        if (size(holes) == 0)
            throw regenError("No round through-holes found on the selected face.", ["face"]);

        // part edge = the face's outer boundary only. Group the face's edges into loops (edges sharing a vertex) and
        // take the loop with the largest bounding box: it encloses every inner loop, so slots, cut-outs and other
        // holes are never measured as edge.
        var remaining = evaluateQuery(context, edges);
        var outerLoop = qNothing();
        var outerSize = -1 * meter;
        while (size(remaining) > 0)
        {
            var loop = [remaining[0]];
            remaining = remaining[1:size(remaining)];
            var grew = true;
            while (grew)
            {
                grew = false;
                var rest = [];
                for (var c in remaining)
                {
                    const touching = evaluateQuery(context, qIntersection([qUnion(loop),
                            qAdjacent(c, AdjacencyType.VERTEX, EntityType.EDGE)]));
                    if (size(touching) > 0)
                    {
                        loop = append(loop, c);
                        grew = true;
                    }
                    else
                        rest = append(rest, c);
                }
                remaining = rest;
            }
            const box = evBox3d(context, { "topology" : qUnion(loop), "cSys" : cs });
            const extent = norm(box.maxCorner - box.minCorner);
            if (extent > outerSize)
            {
                outerSize = extent;
                outerLoop = qUnion(loop);
            }
        }
        const outer = outerLoop;
        const required = definition.factor * definition.thickness;
        var bad = [];
        var worst = inf * meter;
        for (var h in holes)
        {
            const d = evDistance(context, { "side0" : h, "side1" : outer }).distance;
            worst = min(worst, d);
            if (d < required - TOL)
                bad = append(bad, h);
        }

        const summary = "required >= " ~ toString(roundToPrecision(required / millimeter, 3)) ~ " mm, closest " ~
            toString(roundToPrecision(worst / millimeter, 3)) ~ " mm";
        if (size(bad) > 0)
        {
            setErrorEntities(context, id, { "entities" : qUnion(bad) });
            reportFeatureWarning(context, id, toString(size(bad)) ~ " of " ~ toString(size(holes)) ~
                " holes too close to the edge (" ~ summary ~ ")");
        }
        else
        {
            reportFeatureInfo(context, id, "All " ~ toString(size(holes)) ~ " holes pass (" ~ summary ~ ")");
        }
    });
